\midrule
BiLSTM-CRF & 86.1 & 85.3 \\
BERT-NER & 92.8 & 92.0 \\
Ours & 93.5 & 92.7 \\
\bottomrule
\end{tabular}
\end{table}
Figure~\ref{fig:ner_curve} shows learning curves.
\begin{figure}[h]\centering\caption{NER learning curves.}\label{fig:ner_curve}\end{figure}
Ours achieves F1 of 93.5, a new SOTA on CoNLL-2003.

\bibliography{refs}
\end{document}

